SET TimeZone='UTC';
CREATE SCHEMA raw;
CREATE TABLE raw.people AS SELECT * FROM read_csv('C:/Users/longxiu/Documents/ChatGPT/customer-economics-lab/data/people.csv', header=true, columns={'person_id': 'VARCHAR', 'record_created_at': 'TIMESTAMP', 'attributes_recorded_at': 'TIMESTAMP', 'age_band': 'VARCHAR', 'household_type': 'VARCHAR', 'primary_need': 'VARCHAR', 'region': 'VARCHAR'}, nullstr='', strict_mode=true);
CREATE VIEW people AS SELECT * FROM raw.people;
CREATE TABLE raw.subscription_periods AS SELECT * FROM read_csv('C:/Users/longxiu/Documents/ChatGPT/customer-economics-lab/data/subscription_periods.csv', header=true, columns={'period_id': 'VARCHAR', 'subscription_id': 'VARCHAR', 'person_id': 'VARCHAR', 'period_start': 'DATE', 'period_end': 'DATE', 'renewal_due_at': 'TIMESTAMP', 'renewal_outcome': 'VARCHAR', 'cancellation_effective_at': 'TIMESTAMP', 'plan_tier': 'VARCHAR'}, nullstr='', strict_mode=true);
CREATE VIEW subscription_periods AS SELECT * FROM raw.subscription_periods;
CREATE TABLE raw.transactions AS SELECT * FROM read_csv('C:/Users/longxiu/Documents/ChatGPT/customer-economics-lab/data/transactions.csv', header=true, columns={'transaction_id': 'VARCHAR', 'person_id': 'VARCHAR', 'period_id': 'VARCHAR', 'occurred_at': 'TIMESTAMP', 'transaction_type': 'VARCHAR', 'related_transaction_id': 'VARCHAR', 'order_id': 'VARCHAR', 'charge_type': 'VARCHAR', 'quantity': 'INTEGER', 'unit_price': 'DECIMAL(12,2)', 'gross_amount': 'DECIMAL(12,2)', 'discount_amount': 'DECIMAL(12,2)', 'refund_amount': 'DECIMAL(12,2)', 'variable_cost': 'DECIMAL(12,2)'}, nullstr='', strict_mode=true);
CREATE VIEW transactions AS SELECT * FROM raw.transactions;
CREATE TABLE raw.product_events AS SELECT * FROM read_csv('C:/Users/longxiu/Documents/ChatGPT/customer-economics-lab/data/product_events.csv', header=true, columns={'event_id': 'VARCHAR', 'person_id': 'VARCHAR', 'occurred_at': 'TIMESTAMP', 'event_type': 'VARCHAR', 'platform': 'VARCHAR'}, nullstr='', strict_mode=true);
